function validate([patterns, word]) {
  if (!Array.isArray(patterns) || patterns.length < 1 || patterns.length > 100) return 'patterns needs 1 to 100 strings.';
  for (const p of patterns) {
    if (typeof p !== 'string' || p.length < 1 || p.length > 100) return 'Each pattern has 1 to 100 characters.';
    if (!/^[a-z]+$/.test(p)) return 'Patterns may contain only lowercase English letters.';
  }
  if (typeof word !== 'string' || word.length < 1 || word.length > 100) return 'word needs 1 to 100 characters.';
  if (!/^[a-z]+$/.test(word)) return 'word may contain only lowercase English letters.';
  return null;
}

