function numOfStrings(patterns, word) {
  let total = 0;
  for (const p of patterns) {
    let found = false;
    for (let start = 0; start + p.length <= word.length && !found; start++) {
      let k = 0;
      while (k < p.length && word[start + k] === p[k]) k++;
      if (k === p.length) found = true;
    }
    if (found) total++;
  }
  return total;
}

