function generate(rand, size) {
  const large = size === 'large';
  const letters = rand() < 0.5 ? 'ab' : (large ? 'abcdefghijklmnopqrstuvwxyz' : 'abc');
  const pick = () => letters[Math.floor(rand() * letters.length)];
  const randomText = (len) => Array.from({ length: len }, pick).join('');
  const wordLength = large ? 100 : 1 + Math.floor(rand() * 10);
  let word;
  if (rand() < 0.4) {
    const period = randomText(1 + Math.floor(rand() * 4));
    word = period.repeat(Math.ceil(wordLength / period.length)).slice(0, wordLength);
  } else {
    word = randomText(wordLength);
  }
  const count = large ? 100 : 1 + Math.floor(rand() * 6);
  const maxLength = large ? 100 : 5;
  const patterns = [];
  for (let i = 0; i < count; i++) {
    const roll = rand();
    if (roll < 0.45) {
      const start = Math.floor(rand() * word.length);
      const end = start + 1 + Math.floor(rand() * (word.length - start));
      patterns.push(word.slice(start, end));
    } else if (roll < 0.75) {
      const start = Math.floor(rand() * word.length);
      const end = start + 1 + Math.floor(rand() * (word.length - start));
      const piece = word.slice(start, end).split('');
      const at = Math.floor(rand() * piece.length);
      piece[at] = pick();
      patterns.push(piece.join(''));
    } else {
      patterns.push(randomText(1 + Math.floor(rand() * maxLength)));
    }
  }
  return [patterns, word];
}
